actions.script:
if (!ec.user.userId) throw new Error('A conversation operation needs a logged-in user');
if (!ec.user.hasPermission('AgentUse')) throw new Error('This needs the AgentUse permission');
const operations = {
    start: ['startServiceName', 'org.moqui.agent.AgentServices.start#AgentRun'],
    cancel: ['cancelServiceName', 'org.moqui.agent.AgentServices.cancel#AgentRun'],
    input: ['inputServiceName', 'org.moqui.agent.AgentServices.submit#AgentInput'],
    events: ['eventsServiceName', 'org.moqui.agent.AgentServices.get#AgentRunEvents']
};
if (!Object.hasOwn(operations, operation)) throw new Error('Unknown conversation operation');
const row = ec.entity.find('moqui.agent.AgentConversation').condition('conversationId', conversationId).disableAuthz().one();
if (!row || row.get('userId') !== ec.user.userId) throw new Error('No agent conversation ' + conversationId);
const [field, nativeService] = operations[operation], service = row.get(field) || nativeService;
if (service.startsWith('org.moqui.agent.ConversationServices.')) throw new Error('Name an implementation service for ' + field);
const input = Object.assign({}, context);
// Custom services need no local AgentRun. Native services accept the explicit run or the active one.
if (operation !== 'start' && service === nativeService) {
    input.runId = runId || row.get('activeRunId');
    const run = input.runId && ec.entity.find('moqui.agent.AgentRun').condition('runId', input.runId).disableAuthz().one();
    if (!run || run.get('conversationId') !== conversationId || run.get('userId') !== ec.user.userId)
        throw new Error('No agent run in conversation ' + conversationId);
}
Object.assign(context, ec.service.sync().name(service).parameters(input).call() || {});
